export const VERSIONS={short:{label:'Corta',count:36,perAxis:3,minutes:5},full:{label:'Completa',count:60,perAxis:5,minutes:9},extreme:{label:'Extrema',count:240,perAxis:20,minutes:30}};
export function questionSet(bank,version='short'){const v=VERSIONS[version];if(!v)throw Error('Versión desconocida');return bank.filter(q=>q.order<=v.perAxis).sort((a,b)=>a.order-b.order||a.axis-b.axis)}
export function validAnswer(v){return Number.isInteger(v)&&v>=0&&v<=4}
export function scoreProfile(questions,answers){return Array.from({length:12},(_,axis)=>{const found=questions.filter(q=>q.axis===axis&&validAnswer(answers[q.id]));if(!found.length)return null;const total=found.reduce((s,q)=>s+(answers[q.id]-2)*q.direction,0);return Math.round(50+25*total/found.length)})}
export function isComplete(questions,answers){return questions.length>0&&questions.every(q=>validAnswer(answers[q.id]))}
export function sharedAxes(entities){return Array.from({length:12},(_,i)=>i).filter(i=>entities.every(e=>Number.isFinite(e.profile[i])))}
export const sameAffinity=(a,b)=>!!a&&!!b&&Math.abs(a.distance-b.distance)<1e-9;
export function rankProfiles(profile,entities){const axes=sharedAxes(entities).filter(i=>Number.isFinite(profile[i]));if(axes.length<3)return{axes,ranked:[]};const ranked=entities.map(entity=>{const distance=axes.reduce((s,i)=>s+Math.abs(profile[i]-entity.profile[i]),0)/axes.length;return {entity,distance,score:Math.round(100-distance)}}).sort((a,b)=>a.distance-b.distance||a.entity.name.localeCompare(b.entity.name,'es'));return{axes,ranked}}
export function restoreState(raw,bank){try{const d=JSON.parse(raw);if(d?.schema!==1||!VERSIONS[d.version])return null;const set=questionSet(bank,d.version),allowed=new Set(set.map(q=>q.id));const answers=Object.fromEntries(Object.entries(d.answers||{}).filter(([id,v])=>allowed.has(id)&&validAnswer(v)));const cursor=Number.isInteger(d.cursor)?Math.min(Math.max(0,d.cursor),set.length-1):0;return{schema:1,version:d.version,answers,cursor,completed:isComplete(set,answers)&&d.completed===true}}catch{return null}}
